import type { DistrictScore } from "../api/client";
import type { Strings } from "../i18n";

interface Props {
  t: Strings;
  ranking?: DistrictScore[];
  loading: boolean;
}

/** Ranked horizontal bars, one hue, largest first; the figure is printed beside each bar. */
export function RankingPanel({ t, ranking, loading }: Props) {
  return (
    <section className="card ranking" aria-label={t.ranking} aria-busy={loading} data-testid="ranking">
      <h2>{t.ranking}</h2>
      {loading && !ranking && <p className="muted">{t.loading}</p>}
      <ol>
        {ranking?.map((d) => (
          <li key={d.districtId} title={`P25 ${Math.round(d.p25)} · P75 ${Math.round(d.p75)}`}>
            <span className="rank">{d.rank}.</span>
            <span className="district">{d.name}</span>
            <span className="bar-track" aria-hidden="true">
              <span className="bar-fill" style={{ width: `${Math.max(2, Math.round(d.score))}%` }} />
            </span>
            <span className="bar-value">{Math.round(d.score)}</span>
          </li>
        ))}
      </ol>
    </section>
  );
}
