import type { AccessResponse } from "../api/client";
import type { Strings } from "../i18n";

interface Props {
  t: Strings;
  access?: AccessResponse;
  loading: boolean;
  error?: string;
  minutes: number[];
  onClear: () => void;
}

const fmtMinutes = (seconds: number) => Math.max(1, Math.round(seconds / 60));

/**
 * The selected point: a hero score, then a meter list - one row per category with the
 * time to the nearest place as a bar against the 15-minute limit.
 */
export function PlaceCard({ t, access, loading, error, minutes, onClear }: Props) {
  if (error) {
    return (
      <section className="card place" role="alert">
        <p className="error">{error}</p>
        <button type="button" className="link" onClick={onClear}>
          {t.clear}
        </button>
      </section>
    );
  }
  if (!access) {
    return (
      <section className="card place" aria-live="polite">
        <p className="muted">{loading ? t.loading : t.clickHint}</p>
      </section>
    );
  }

  const rows = [...access.categories]
    .filter((c) => c.weight > 0)
    .sort((a, b) => (a.seconds ?? Infinity) - (b.seconds ?? Infinity));
  const title = access.address?.label ?? `${access.point.lat.toFixed(5)}, ${access.point.lon.toFixed(5)}`;

  return (
    <section className="card place" aria-label={title} aria-busy={loading} data-testid="place-card">
      <header className="place-header">
        <div>
          <h2 data-testid="place-title">{title}</h2>
          {access.address?.sublabel && <p className="muted">{access.address.sublabel}</p>}
        </div>
        <button type="button" className="icon-button" aria-label={t.clear} onClick={onClear}>
          ×
        </button>
      </header>

      <div className="hero">
        <span className="hero-value" data-testid="score">
          {Math.round(access.score)}
        </span>
        <span className="hero-caption">
          {t.score} <span className="muted">{t.outOf}</span>
        </span>
      </div>

      <h3>{t.nearest}</h3>
      <ul className="meters">
        {rows.map((c) => (
          <li key={c.category} data-testid={`category-${c.category}`} title={c.poi?.name ?? undefined}>
            <span className="meter-name">
              {t.categories[c.category]}
              {c.poi?.name && <span className="meter-poi">{c.poi.name}</span>}
            </span>
            <span className="meter-track" aria-hidden="true">
              <span className="meter-fill" style={{ width: `${Math.round(c.score * 100)}%` }} />
            </span>
            <span className="meter-value">
              {c.seconds == null ? t.unreachable : `${fmtMinutes(c.seconds)} ${t.min}`}
            </span>
          </li>
        ))}
      </ul>

      <h3>{t.isochrones}</h3>
      <ul className="iso-legend">
        {minutes.map((m, i) => (
          <li key={m}>
            <span className={`iso-swatch iso-${i}`} aria-hidden="true" />
            {m} {t.min}
          </li>
        ))}
      </ul>
    </section>
  );
}
