import type { Strings } from "../i18n";
import { HEAT_RAMP } from "../scoring";

export function Legend({ t, dark }: { t: Strings; dark: boolean }) {
  const ramp = dark ? HEAT_RAMP.dark : HEAT_RAMP.light;
  return (
    <figure className="legend" aria-label={t.legendTitle}>
      <figcaption>{t.legendTitle}</figcaption>
      <div className="legend-bar" style={{ background: `linear-gradient(to right, ${ramp.join(", ")})` }} />
      <div className="legend-ticks">
        <span>0 · {t.legendLow}</span>
        <span>50</span>
        <span>{t.legendHigh} · 100</span>
      </div>
    </figure>
  );
}
